        quote! {
            requires
                #((#reqs)),*
        }
    } else {
        TokenStream::new()
    };

    // Output types are a bit tricky
    // because of the lack of named output params.

    let (out_params_ret, ens_stream) = if out_params.len() == 0 {
        let ens_stream = if enss.len() > 0 {
            quote! {
                ensures
                    #((#enss)),*
            }
